DELETE FROM t1; INSERT INTO t1(x) VALUES('[null,123,4.5,"six",[7,8],{"b":9}]'); WITH c(y) AS (VALUES(0),(1),(2),(3),(4),(5),(6)) INSERT INTO result SELECT y,x->y,CASE WHEN subtype(x->y) THEN 'json' ELSE typeof(x->y) END,x->>y,CASE WHEN subtype(x->>y) THEN 'json' ELSE typeof(x->>y) END,json_extract(x,format('$[%d]',y)),CASE WHEN subtype(json_extract(x,format('$[%d]',y))) THEN 'json' ELSE typeof(json_extract(x,format('$[%d]',y))) END FROM c,t1 ORDER BY y;